mapper.select:
SELECT
FROM contract_template WHERE 1 = 1
ORDER BY contract_type ASC, is_default DESC, id DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT EXISTS(
    SELECT 1
    FROM contract_template
    WHERE is_default = 1
      AND contract_type = #{contractType}
      AND id != #{id}
)

mapper.update:
UPDATE contract_template
SET is_default = 0
WHERE is_default = 1
  AND contract_type = #{contractType}
  AND id != #{id}
